// Valida el JSON de P1 contra el esquema y prepara la fila de `clasificaciones`.
const r = $input.first().json;
const req = $('Armar llamada P1').first().json;
const ticket = $('Guardar ticket').first().json;
const ENUM = {
  severidad: ['P1','P2','P3','P4'],
  origen_falla: ['truora','fuente_externa_gobierno','meta_whatsapp','integracion_cliente','usuario_final','no_aplica','indeterminado'],
  accion_sugerida: ['escalar_ingenieria','comunicado_proactivo','responder_con_kb','pedir_datos'],
};
let c = {}, valido = true, error = null;
try { c = JSON.parse(r.choices[0].message.content); }
catch (e) { valido = false; error = 'JSON inválido: ' + e.message; }
for (const [campo, permitidos] of Object.entries(ENUM)) {
  if (!permitidos.includes(c[campo])) { valido = false; error = (error ? error + '; ' : '') + `${campo} fuera de esquema: ${c[campo]}`; c[campo] = null; }
}
const conf = Number(c.confianza);
return [{ json: {
  ticket_id: ticket.id,
  ticket_ref: ticket.ticket_ref,
  cliente: ticket.cliente,
  modelo: req.modelo,
  prompt_version: 'P1-v2',
  producto: c.producto ?? null,
  pais: c.pais ?? null,
  ambiente: c.ambiente ?? null,
  tipo: c.tipo ?? null,
  origen_falla: c.origen_falla,
  codigo_motivo: c.codigo_motivo ?? null,
  severidad: c.severidad,
  confianza: Number.isFinite(conf) ? Math.min(Math.max(conf, 0), 1) : null,
  justificacion: c.justificacion ?? null,
  datos_faltantes: Array.isArray(c.datos_faltantes) ? c.datos_faltantes : [],
  requiere_escalamiento: c.requiere_escalamiento === true,
  accion_sugerida: c.accion_sugerida,
  json_crudo: c,
  json_valido: valido,
  error,
  latencia_ms: Date.now() - req.inicio,
  tokens_entrada: r.usage?.prompt_tokens ?? null,
  tokens_salida: r.usage?.completion_tokens ?? null,
}}];

